('12a017ac-b213-518a-9096-a71a39d234a7','27fef7e5-0786-5667-8b2c-09291cf318c9',1,'verb','B2',null,'W3','( past tense and past participle swept / swept / )','[{"phrase":"sweep the board","register":null,"definition_en":"to win everything that can be won, especially very easily","translation":"برای بردن هر چیزی که می توان به دست آورد، مخصوصاً خیلی راحت","example":"","example_translation":"","example_audio_url":""},{"phrase":"sweep somebody off their feet","register":null,"definition_en":"to make someone feel suddenly and strongly attracted to you in a romantic way","translation":"کاری کنید که کسی به طور ناگهانی و شدید به شکلی عاشقانه به شما جذب شود","example":"Jill’s been swept off her feet by an older man.","example_translation":"یک مرد مسن‌تر جیل را از پا درآورده است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000604849.mp3"}]'::jsonb),
('77ae03dd-8eb1-5da8-bca2-5e86e1f7219a','27fef7e5-0786-5667-8b2c-09291cf318c9',2,'noun','B2',null,null,'[ countable ]','[{"phrase":"the sweep of something","register":null,"definition_en":"a long curved line or area of land","translation":"یک خط منحنی طولانی یا مساحت زمین","example":"the wide sweep of lawn","example_translation":"جاروی وسیع چمن","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001599424.mp3"},{"phrase":"the sweeps","register":null,"definition_en":"a period of time during the year when television stations try to find out which shows are the most popular","translation":"دوره زمانی در طول سال که ایستگاه های تلویزیونی سعی می کنند دریابند کدام برنامه ها محبوب ترین هستند","example":"","example_translation":"","example_audio_url":""}]'::jsonb),
